import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import type { PrimitiveProps } from "../primitives";

const BASE = "#B4451F";
const LINE = "#9A3717";
const LINE_SOFT = "#A63D1A";

// Perpendicular period of the 45deg stripe pattern, in px.
const STRIPE_PERIOD = 30;
// Vertical travel needed for one seamless repeat of a 45deg pattern.
const CYCLE_Y = STRIPE_PERIOD * Math.SQRT2;

const BurntOrangeDiagonalDrift: React.FC<PrimitiveProps> = ({ fps }) => {
  const frame = useCurrentFrame();
  const safeFps = fps && fps > 0 ? fps : 30;

  // Continuous upward drift, wrapped so it never grows unbounded.
  const driftSpeed = CYCLE_Y / (7 * safeFps); // one full stripe cycle per 7s
  const offsetY = -((frame * driftSpeed) % CYCLE_Y);

  // Slow, endless breathing of the stripe contrast + a wide warm glow.
  const breathe = Math.sin((frame / safeFps) * ((Math.PI * 2) / 19));
  const stripeOpacity = 0.55 + breathe * 0.12;

  const glowPhase = Math.sin((frame / safeFps) * ((Math.PI * 2) / 26));
  const glowX = 50 + glowPhase * 12;
  const glowY = 38 + Math.cos((frame / safeFps) * ((Math.PI * 2) / 34)) * 10;

  // Very slight easing wobble on the drift for a hand-made feel (periodic).
  const wobble = interpolate(
    Math.sin((frame / safeFps) * ((Math.PI * 2) / 23)),
    [-1, 1],
    [-1.5, 1.5],
    { easing: Easing.inOut(Easing.ease) }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: BASE, overflow: "hidden" }}>
      {/* Thin darker diagonal pinstripes, drifting up forever */}
      <div
        style={{
          position: "absolute",
          left: -200,
          top: -200,
          width: 1080 + 400,
          height: 1920 + 400,
          opacity: stripeOpacity,
          transform: `translateY(${offsetY + wobble}px)`,
          backgroundImage: `repeating-linear-gradient(45deg, ${LINE} 0px, ${LINE} 1.5px, rgba(0,0,0,0) 1.5px, rgba(0,0,0,0) ${STRIPE_PERIOD}px)`,
        }}
      />

      {/* A second, wider and softer stripe layer at half speed for depth */}
      <div
        style={{
          position: "absolute",
          left: -200,
          top: -200,
          width: 1080 + 400,
          height: 1920 + 400,
          opacity: 0.35,
          transform: `translateY(${-(((frame * driftSpeed) / 2) % (CYCLE_Y * 3))}px)`,
          backgroundImage: `repeating-linear-gradient(45deg, ${LINE_SOFT} 0px, ${LINE_SOFT} 3px, rgba(0,0,0,0) 3px, rgba(0,0,0,0) ${STRIPE_PERIOD * 3}px)`,
        }}
      />

      {/* Soft warm glow that wanders slowly — keeps foreground readable */}
      <AbsoluteFill
        style={{
          backgroundImage: `radial-gradient(60% 45% at ${glowX}% ${glowY}%, rgba(214, 106, 56, 0.40) 0%, rgba(214, 106, 56, 0.14) 45%, rgba(214, 106, 56, 0) 75%)`,
        }}
      />

      {/* Gentle vignette to settle the edges */}
      <AbsoluteFill
        style={{
          backgroundImage:
            "radial-gradient(80% 60% at 50% 50%, rgba(0,0,0,0) 40%, rgba(66, 22, 8, 0.30) 100%)",
        }}
      />
    </AbsoluteFill>
  );
};

export default BurntOrangeDiagonalDrift;
